            current_length = 0
            consecutive_elements = []
            for i in range(len(self.stack)):
                if self.stack[i] == self.stack[i + 1]:
                    current_length += 1
                else:
                    consecutive_elements.append(current_length)
                    current_length = 0
            max_length = max(consecutive_elements)
            return max_length
        else:
