            return min(self.stack)
        else:
            print("Stack is empty. No minimum element")

    def reverse(self):
        if not self.is_empty():
            self.stack = self.stack[::-1]

    def is_empty(self):
        return len(self.stack) == 0

    def is_full(self):
        return len(self.stack) == self.capacity

    def remove_all(self, item):
