        if title in self.title_index:
            self.title_index[title].append(book)
        else:
            self.title_index[title] = [book]

        # Update the ISBN index
        self.isbn_index[isbn] = book

    def get_title_by_isbn(self, isbn):
        if isbn in self.isbn_index:
            return self.isbn_index[isbn].title
        else:
