            books_to_delete = self.title_index[title]
            for book in books_to_delete:
                self.books.remove(book)
                del self.isbn_index[book.isbn]

            del self.title_index[title]
        else:
            raise ValueError("Book with the given title not found.")

    def delete_by_isbn(self, isbn):
