def find_strings(lst, letter):
    # Custom implementation of a set using a dictionary with an OrderedDict to preserve order
    class CustomSet:
        def __init__(self):
            self.data = {}

        def add(self, item):
            if item not in self.data:
                self.data[item] = True

        def __contains__(self, item):
            return item in self.data

        def __len__(self):
            return len(self.data)

    # Custom implementation of a list using an array with an OrderedDict to preserve order
    class CustomList:
        def __init__(self):
            self.data = []

        def append(self, item):
            self.data.append(item)

        def __getitem__(self, index):
            return self.data[index]

        def __len__(self):
            return len(self.data)

    # Recursive function to find strings containing the letter
    def recursive_find(lst, letter, index, result):
        if index == len(lst):
            return result
        elif lst[index] == letter:
            result.append(lst[index])
            recursive_find(lst, letter, index + 1, result)
        else:
            recursive_find(lst, letter, index + 1, result)

    # Sort the results using a custom implementation of merge sort
    def custom_merge_sort(lst):
        if len(lst) <= 1:
            return lst
        mid = len(lst) // 2
        left = lst[:mid]
        right = lst[mid:]
        left = custom_merge_sort(left)
        right = custom_merge_sort(right)
        return custom_merge(left, right)

    # Custom merge function for merge sort
    def custom_merge(left, right):
        result = []
        i = j = 0
        while i < len(left) and j < len(right):
            if left[i] < right[j]:
                result.append(left[i])
                i += 1
            else:
                result.append(right[j])
                j += 1
        result.extend(left[i:])
        result.extend(right[j:])
        return result

    # Find the strings containing the letter and sort them
    result = custom_merge_sort(CustomList(find_strings(CustomSet(), letter)))
    return [str(x) for x in result]

