        if start > end:
            return

        mid = (start + end) // 2

        if strings[mid].lower().count(letter.lower()) > 0:
            result.add(strings[mid])

        helper(strings, letter, start, mid - 1)
        helper(strings, letter, mid + 1, end)

    helper(strings, letter, 0, len(strings) - 1)

